const truncate = (s, n) => (typeof s === "string" && s.length > n ? s.slice(0, n) : s ?? null);
const clean = (v) => (v === undefined || v === "" ? null : v);

const normalizePhone = (phone) => {
  if (!phone) return null;

  // Remove tudo que não é número
  let digits = String(phone).replace(/\D/g, "");

  // Remove código do país caso venha duplicado (5555...)
  while (digits.startsWith("5555")) {
    digits = digits.slice(2);
  }

  // Se não tiver DDI, adiciona 55
  if (!digits.startsWith("55")) {
    digits = "55" + digits;
  }

  // Após o DDI devem existir DDD + número
  const ddd = digits.slice(2, 4);
  let number = digits.slice(4);

  // Celular antigo (8 dígitos) -> adiciona 9
  if (number.length === 8) {
    number = "9" + number;
  }

  return `55${ddd}${number}`;
};

// emails[] e phones[] vêm em lista (pode achar mais de um). Prioriza
// email de trabalho e telefone celular; evita "não ligar" se tiver opção.
const pickEmail = (emails) => {
  if (!Array.isArray(emails) || !emails.length) return null;
  const trabalho = emails.find((e) => e.type === "work");
  return (trabalho || emails[0])?.email ?? null;
};

const pickPhone = (phones) => {
  if (!Array.isArray(phones) || !phones.length) return null;
  const ligavel = phones.filter((p) => !p.doNotCall);
  const pool = ligavel.length ? ligavel : phones;
  const celular = pool.find((p) => p.type === "mobile");
  return (celular || pool[0])?.number ?? null;
};

// employeeCount vem como {exact, min, max}; monta um texto só.
const empresaTamanho = (ec) => {
  if (!ec) return null;
  if (ec.exact != null) return String(ec.exact);
  if (ec.min != null && ec.max != null) return `${ec.min}-${ec.max}`;
  return ec.min != null ? String(ec.min) : ec.max != null ? String(ec.max) : null;
};

// lead: o registro original desse item do loop (vindo do Postgres).
// contato: resultado do node "Enrich Contacts" pra esse mesmo item.
// empresa: resultado deste mesmo item ($json), pois este Code roda
// logo depois do "Enrich Companies".
const lead    = $('Loop Over Items').item.json;
const contato = ($('Enrich Contacts').item.json.results || [])[0] || null;
const empresa = ($json.results || [])[0] || null;

// "error" aparece no item quando a Lusha não achou/recusou aquele
// contato ou empresa específico (ex: NOT_FOUND).
const contatoFalhou = !contato || contato.error;

const fullName =
  contato?.fullName ||
  [contato?.firstName, contato?.lastName].filter(Boolean).join(" ").trim() ||
  lead.nome ||
  null;

return [{
  json: {
    id: lead.id, // usado pelo filtro do node "Atualiza os dados"
    nome: clean(fullName),
    cargo: clean(contato?.jobTitle?.title) ?? lead.cargo ?? null,
    email: pickEmail(contato?.emails),
    telefone: normalizePhone(pickPhone(contato?.phones)),
    linkedin_url: clean(contato?.socialLinks?.linkedin) ?? lead.linkedin_url ?? null,
    empresa_nome: clean(empresa?.name) ?? clean(contato?.company?.name) ?? lead.empresa_nome ?? null,
    empresa_site: clean(empresa?.domain) ?? clean(contato?.company?.domain) ?? lead.empresa_site ?? null,
    empresa_setor: clean(empresa?.subIndustry) ?? clean(empresa?.industry) ?? clean(contato?.company?.industry) ?? null,
    empresa_tamanho: empresaTamanho(empresa?.employeeCount),
    empresa_descricao: truncate(empresa?.description, 4000),
    dados_enriquecimento: { contato: contato ?? null, empresa: empresa ?? null },
    etapa: contatoFalhou ? "enrich_falhou" : "enrich",
  },
}];

